import sys
from collections import deque

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_word = False

def build_trie(words):
    """Build a trie from the word list for efficient prefix checking."""
    root = TrieNode()
    for word in words:
        node = root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_word = True
    return root

def load_words(filename):
    """Load words from the dictionary file."""
    with open(filename, 'r') as f:
        return [word.strip().upper() for word in f if word.strip()]

def get_neighbors(row, col, rows, cols):
    """Get all valid neighboring positions including diagonals."""
    neighbors = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols:
                neighbors.append((new_row, new_col))
    return neighbors

def find_words_optimized(board, trie, min_length=3):
    """Find all valid words on the Boggle board using trie for optimization."""
    rows = len(board)
    cols = len(board[0])
    found_words = set()

    # Start from each cell
    for start_row in range(rows):
        for start_col in range(cols):
            start_char = board[start_row][start_col]

            # Use DFS with trie for efficient pruning
            stack = [(start_row, start_col, start_char, {(start_row, start_col)})]

            while stack:
                row, col, current_word, visited = stack.pop()

                # Check if current word is valid
                node = trie
                for char in current_word:
                    if char not in node.children:
                        break
                    node = node.children[char]
                else:
                    if node.is_word and len(current_word) >= min_length:
                        found_words.add(current_word)

                # Explore neighbors
                for neighbor_row, neighbor_col in get_neighbors(row, col, rows, cols):
                    if (neighbor_row, neighbor_col) not in visited:
                        new_char = board[neighbor_row][neighbor_col]
                        new_word = current_word + new_char

                        # Only continue if it's a valid prefix
                        if new_word[0] in trie.children:
                            node = trie
                            valid_prefix = True
                            for char in new_word:
                                if char not in node.children:
                                    valid_prefix = False
                                    break
                                node = node.children[char]

                            if valid_prefix:
                                new_visited = visited.copy()
                                new_visited.add((neighbor_row, neighbor_col))
                                stack.append((neighbor_row, neighbor_col, new_word, new_visited))

    return found_words

def solve_boggle_optimized():
    """Main function to solve the Boggle puzzle with optimization."""
    # Define the Boggle board
    board = [
        "ABRL",
        "EITE", 
        "IONS",
        "FPEI"
    ]

    # Load dictionary and build trie
    words = load_words("words_alpha.txt")
    trie = build_trie(words)

    # Find all possible words
    found_words = find_words_optimized(board, trie)

    if not found_words:
        print("No words found!")
        return

    # Find the longest word(s)
    max_length = max(len(word) for word in found_words)
    longest_words = [word for word in found_words if len(word) == max_length]

    # If multiple words have same length, return alphabetically first
    longest_words.sort()
    result = longest_words[0]

    print(f"Longest word found: {result}")
    print(f"Length: {max_length}")
    print(f"Total words found: {len(found_words)}")

if __name__ == "__main__":
    solve_boggle_optimized()
